ALTER TABLE pitlane.runtime ADD COLUMN IF NOT EXISTS billing_mode text NOT NULL DEFAULT 'disabled' CHECK(billing_mode IN('disabled','sandbox','live'));
CREATE TABLE IF NOT EXISTS pitlane.billing_customers(tenant_id uuid PRIMARY KEY REFERENCES pitlane.tenants,provider_customer_id text NOT NULL UNIQUE,origin text NOT NULL CHECK(origin IN('sandbox','live')));
CREATE TABLE IF NOT EXISTS pitlane.billing_subscriptions(provider_subscription_id text PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES pitlane.tenants,provider_customer_id text NOT NULL REFERENCES pitlane.billing_customers(provider_customer_id),plan_version text NOT NULL);
CREATE OR REPLACE FUNCTION pitlane.subscription_settle(invoice text,t uuid,subscription text,units integer,period_start timestamptz,period_end timestamptz,paid bigint,origin text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE journal uuid;source text='invoice/'||invoice;BEGIN IF units<0 OR paid<0 OR period_end<=period_start OR origin NOT IN('sandbox','live') THEN RAISE EXCEPTION 'INVALID_SETTLEMENT';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(source,0));IF EXISTS(SELECT FROM pitlane.journals WHERE source_key=source) THEN RETURN;END IF;INSERT INTO pitlane.entitlement_lots(tenant_id,source_key,granted,starts_at,ends_at,origin) VALUES(t,source,units,period_start,period_end,CASE WHEN origin='live' THEN 'customer' ELSE 'internal' END);INSERT INTO pitlane.journals(tenant_id,source_key,origin) VALUES(t,source,origin) RETURNING id INTO journal;INSERT INTO pitlane.journal_lines VALUES(journal,'processor_receivable','USD',2,paid),(journal,'subscription_obligation','USD',2,-paid);END $$;
CREATE OR REPLACE FUNCTION pitlane.receive_payment_event(id text,account text,origin text,kind text,v jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ BEGIN IF origin NOT IN('sandbox','live') THEN RAISE EXCEPTION 'INVALID_PAYMENT_ENVIRONMENT';END IF;INSERT INTO pitlane.payment_inbox(event_id,provider_account,origin,event_type,payload) VALUES(id,account,origin,kind,v) ON CONFLICT DO NOTHING;RETURN FOUND;END $$;
CREATE OR REPLACE FUNCTION pitlane.payment_events(maximum integer) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT coalesce(jsonb_agg(e),'[]'::jsonb) FROM(SELECT * FROM pitlane.payment_inbox WHERE processed_at IS NULL ORDER BY received_at LIMIT least(maximum,100)) e $$;
CREATE OR REPLACE FUNCTION pitlane.complete_payment_event(id text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.payment_inbox SET processed_at=now() WHERE event_id=id $$;
CREATE OR REPLACE FUNCTION pitlane.subscription_link(sub text,customer text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT to_jsonb(s) FROM pitlane.billing_subscriptions s WHERE provider_subscription_id=sub AND provider_customer_id=customer $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.subscription_settle(text,uuid,text,integer,timestamptz,timestamptz,bigint,text),pitlane.receive_payment_event(text,text,text,text,jsonb),pitlane.payment_events(integer),pitlane.complete_payment_event(text),pitlane.subscription_link(text,text) TO pitlane_billing;
